// src/services/api.js
const BASE_URL = '';  // CRA proxy

async function request(path, options = {}) {
  const res = await fetch(path, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });

  if (!res.ok) {
    let err = `Request failed: ${res.status}`;
    try {
      const body = await res.json();
      err = body.message || err;
    } catch (e) {}
    throw new Error(err);
  }

  // Inspect content-type:
  const ct = res.headers.get('content-type') || '';
  if (ct.includes('application/json')) {
    // real JSON → parse it
    return res.json();
  } else {
    // plain text → wrap it in an object
    const txt = await res.text();
    return { message: txt };
  }
}

// your exports stay the same:
export function login(body) {
  // now returns a JS object: { message: "string from server" }
  return request('/users/login', { method: 'POST', body: JSON.stringify(body) });
}
// …same for register, postQuestion, etc.
